            { ar: "الإخصاب العشوائي", en: "Random fertilisation", def: "ينتج التباين الجيني أيضًا من الإخصاب العشوائي، حيث تندمج الأمشاج المحتوية على أنواع مختلفة من الجينات لتكوين الزيجوتات.", src: "book", page: 77, links: { ig: ['u2-02'] } }
